-- 2198 🏋️ Exercises from the book "passing-warm-ups-direct-from-guardiola-simeone-ancelotti-emery-sarri-heynckes" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page in #books).  Re-runnable: clears this book's
-- exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'passing-warm-ups-direct-from-guardiola-simeone-ancelotti-emery-sarri-heynckes');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Rhombus circuit with check-aways and one-two', 'passing_unopposed', 'unopposed', 'in_possession', 30, 30, 'Unopposed Practice Example', NULL, 'Warm the body up while sharpening pass quality, receiving angles and timing of check-away movements.', 'Rhombus with four stations A, B, C, D, each with a mannequin standing in as a defender; extra players queue at A.', 'A passes diagonally to B, who has checked away from his mannequin and come back to receive; ball goes on to C who plays a one-two, then a through pass is played for D''s run, and D passes back to the next player at A. Everyone follows their pass to the next station (A to B, B to C, C to D, D to A).', 'Continuous circuit; players rotate by following their pass.', NULL, 'Move away from the mannequin before showing to receive; open the correct body angle; pass at the right moment along the diagonal of the rhombus.', '4 stations plus a queue at A', 5, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 10),
  ('Pass across square past middle defender', 'passing_opposed', 'opposed', 'in_possession', 31, 31, 'Technical Opposed Practice Example', NULL, 'Warm up while practising accurate passing and receiving with awareness of a defender trying to cut the ball out.', 'Several 15 yard squares, groups of three: two passers outside at opposite ends, one defender on the middle line of the square.', 'The two end players pass the ball back and forth through the square; the middle defender shuffles sideways along the middle line to intercept.', 'Defender may only move side to side along the middle line. Rotate the defender after a fixed time or whenever he wins the ball.', NULL, 'Move along your end line to open a passing lane; quality and pace of pass; first touch ready to pass again.', 'groups of 3 (2v1)', 3, 3, '15 x 15 yards', 13.7, 13.7, NULL, false, false, false, NULL, 20),
  ('4v4 plus joker keep-ball and counter-press', 'rondo', 'overload', 'in_possession', 32, 32, 'Global Practice Example', NULL, 'Game-like warm-up for keeping possession under pressure, then reacting to losing the ball with a counter-press.', '20 yard square with 4 blues spread round the outside edges and 4 reds inside; a 12 yard square in the centre holds a yellow joker.', 'Phase one at low pace: blues keep the ball using the joker, who can only move inside the small square, while the reds try to intercept. Phase two: when the reds win it they try to get out of the area and keep the ball, and the blues counter-press to stop them.', 'Reds cannot enter the central 12 yard square. Teams swap roles after a set time.', 'Starts as slow-paced keep-ball; second phase adds the transition (reds escape with the ball, blues counter-press).', 'Use the joker to split the defenders; react instantly on losing the ball.', '4v4+1', 9, 9, '20 x 20 yards (central 12 x 12 yards)', 18.3, 18.3, NULL, false, false, false, NULL, 30),
  ('Passing square with speed-agility stations', 'warm_up', 'unopposed', NULL, 33, 33, 'General Practice Example', NULL, 'General activation combining passing round a square with speed, agility and coordination footwork.', '15 yard square with a player at each corner; inside each side are hurdles, slalom poles, speed rings and ladders.', 'The ball is passed round the outside of the square to the next corner; after passing, each player works through the agility section in front of them (hurdles, pole slalom, single-leg ring hops, ladder footwork) and arrives at the next corner to receive when the ball comes round again.', 'Continuous; players rotate one corner each time.', 'Vary the footwork pattern through the ladders.', NULL, '5-8 players', 5, 8, '15 x 15 yards', 13.7, 13.7, NULL, false, false, false, NULL, 40),
  ('3v3 with target man and gate runs', 'small_sided_game', 'opposed', 'in_possession', 34, 34, 'Special Practice Example', NULL, 'Find the forward target, then support him with a forward run through a gate to finish a lay-off.', '20 x 25 yard area with an end score zone at each end holding a small goal; two pole gates mark the entry to each score zone; 3v3 in the middle and one attacker per team in the score zone he attacks.', 'Coach serves to the team in possession, who try to get the ball into their attacker in the end zone; he lays it off for a teammate who has run forward from the middle through a pole gate to score in the small goal. If the defenders win the ball they quickly find their own attacker and do the same at the other end.', 'Supporting runner must enter through a pole gate and finish with one touch.', NULL, 'Time the forward run to arrive as the lay-off is played; quick switch to attack on winning the ball.', '3v3 + 1 attacker each (8)', 8, 8, '20 x 25 yards', 22.9, 18.3, NULL, true, false, true, NULL, 50),
  ('5v5 bounce game with end support players', 'small_sided_game', 'opposed', 'in_possession', 35, 35, 'Competitive Game Example', NULL, 'Competitive warm-up game using bounce passes off end-line supports to create shots, while defenders track runners.', '20 x 40 yard area with a goal at each end; each team has a keeper and 4 outfield players inside plus 2 support players on the end line they attack, either side of the goal.', 'Normal game to goal, but a team must play into one of its outside players and receive the bounce pass back before shooting. Attackers must move fast to get on the return in a scoring position; defenders must react as soon as the ball goes to an outside player and track the runner.', 'Outside players one touch only. A goal counts only if it comes from a pass by an outside player.', NULL, 'Stay alert; attacker moves early to receive the bounce; defender tracks his man when the ball goes wide.', '5(+2) v 5(+2)', 14, 14, '20 x 40 yards', 36.6, 18.3, NULL, true, true, true, NULL, 60),
  ('Rhombus check or open up to receive', 'passing_unopposed', 'unopposed', 'in_possession', 63, 63, 'Set-up: Checking or ''Open Up'' to Create Space and Receive', NULL, 'Teach receivers to make space by checking away from a cone (marker) or opening up at an angle before receiving.', 'Four players on the corners of a rhombus, each with a cone in front of them standing in for an opponent; shape mirrors a holding mid, two central mids and a forward.', 'Ball moves round the rhombus anti-clockwise. The first receiver checks away from his cone and comes back to receive; the next opens up at an angle, takes a directional first touch and passes on.', NULL, 'Coach reverses the direction (clockwise).', 'Movement timed to the pass; directional first touch; well-weighted pass to the next player.', '4', 4, 4, NULL, NULL, NULL, NULL, false, false, false, NULL, 70),
  ('Rhombus one-two, lay-off, pass in behind', 'passing_unopposed', 'unopposed', 'in_possession', 64, 64, 'Link Play & Decision Making - Example 1', NULL, 'Link play and decision making in a rhombus: one-two, forward pass, lay-off and a final ball in behind.', 'Rhombus of four players (A base, B and C wide, D top), each by a cone acting as a defender, in the centre circle area.', 'A plays a one-two with B (B checks off his cone and comes back), then A passes into D at the top. D checks away, drops to support and lays off to B, who has come in to meet it; B slides a through ball for D spinning round his cone. Repeat the other way using C.', NULL, 'Run it clockwise from the other side with C.', 'Receivers choose where to go rather than just opening up; timing of the spin in behind.', '4', 4, 4, NULL, NULL, NULL, NULL, false, false, true, NULL, 80),
  ('Rhombus one-two, through pass, diagonal into feet', 'passing_unopposed', 'unopposed', 'in_possession', 65, 65, 'Link Play & Decision Making - Example 2', NULL, 'Same rhombus link play but players pick their own movements, leading to a through pass and a diagonal ball into the striker''s feet.', 'Same four-player rhombus with cones as defenders.', 'B checks and drops to take the first pass; A comes across for a short return. B runs round his cone to get A''s through pass, while D steps forward off his cone to receive B''s diagonal pass with his back to goal.', NULL, 'Players free to open up, come inside or drop; top player decides to come short or run in behind.', 'Decision making and timing of movement; technique under functional patterns.', '4', 4, 4, NULL, NULL, NULL, NULL, false, false, true, NULL, 90),
  ('Simple rhombus pass-and-follow circuit', 'passing_unopposed', 'unopposed', 'in_possession', 66, 66, 'Circuit Warm-up Practices', NULL, 'Example of a circuit warm-up: pass and move round a diamond with no specific game link.', 'Diamond of four cones with a player on each (extra player at the start cone).', 'Players pass round the diamond and follow their pass to the next cone.', NULL, NULL, 'Individual tactics of pass and move in small groups.', '5', 4, 5, NULL, NULL, NULL, NULL, false, false, false, NULL, 100),
  ('Directional warm-up bottom to top', 'passing_unopposed', 'unopposed', 'in_possession', 67, 67, 'Directional Warm-up Practices', NULL, 'Example of a directional warm-up: move the ball from bottom to top through a set pattern, then mirror it back.', 'Players A (bottom), B (right), C (centre), D (left), E (top) by cones, F as a central player at the far end.', 'A passes wide to B who checks away and drops; B plays inside to C who checks and comes across; C hits a hard ground pass wide to D stepping forward; D plays to E. Players rotate A to B to C to D to E, then E restarts the mirrored pattern back down.', NULL, 'Repeat as a mirror image in the opposite direction.', 'Check away before receiving; firm ground passes.', '6', 6, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 110),
  ('Mixed circuit-directional warm-up', 'passing_unopposed', 'unopposed', 'in_possession', 68, 68, 'Mixed Warm-up Practices', NULL, 'Example of a mixed warm-up combining a circuit with bottom-to-top passing patterns (not necessarily mirrored).', 'Six players A-F on cones in a hexagon-like shape with B central.', 'A one-two with B, B passes across to C, C to wide D. B moves across then forward to take D''s inside pass and feeds E. E one-two with F, gets the return and slips F in round his cone; F passes back to the start.', NULL, NULL, NULL, '6+', 6, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 120),
  ('Basic rhombus control, pass and move', 'passing_unopposed', 'unopposed', 'in_possession', 73, 73, 'Ancelotti 1', 'Ancelotti (Bayern Munich)', 'Passing and receiving in a rhombus with correct body shape and a controlling touch set up for the next action.', '10 yard rhombus, a player at each cone, extras queue at A.', 'A to B, B steps off his cone to receive and passes to C, same for C to D, D passes to the next player at A. Everyone follows their pass.', '1-2 touches', 'Reverse the direction.', 'Check away from the cone at the right time and angle; control in the direction of the next pass.', '7-9', 7, 9, '10 yard rhombus', 9.1, 9.1, NULL, false, false, false, NULL, 130),
  ('Rhombus drop back and give-and-go', 'passing_unopposed', 'unopposed', 'in_possession', 74, 74, 'Ancelotti 2', 'Ancelotti (Bayern Munich)', 'Rhombus passing with one-twos: drop back to receive and play a give and go.', '10 yard rhombus, extras at A.', 'A passes to B and moves to support; B checks away, drops and plays back to A on the move. A slips B round his cone to complete the give and go; B passes to C and the pattern repeats with C and D, D finishing to the next A.', '1-2 touches', NULL, 'Escape the marker by checking away and dropping; receive on the move.', '7-9', 7, 9, '10 yard rhombus', 9.1, 9.1, NULL, false, false, false, NULL, 140),
  ('Rhombus outside-to-inside and forward', 'passing_unopposed', 'unopposed', 'in_possession', 75, 75, 'Ancelotti 3', 'Ancelotti (Bayern Munich)', 'Support play in a rhombus: one-two from outside to inside then a forward pass.', '10 yard rhombus, extras at A.', 'A passes to B and supports; B checks and drops, returns to A on the move; A drives a ground pass to C who opens up. Same pattern repeats between C and D; D passes to the next starter.', '1-2 touches', NULL, 'Angles of support; hard ground pass; receive on the move.', '7-9', 7, 9, '10 yard rhombus', 9.1, 9.1, NULL, false, false, false, NULL, 150),
  ('Rhombus one-twos and third man run', 'passing_unopposed', 'unopposed', 'in_possession', 76, 76, 'Ancelotti 4', 'Ancelotti (Bayern Munich)', 'One-twos, support play and finding the third man in a rhombus.', '10 yard rhombus, A and A2 at the start cone.', 'A passes to B and supports; B lays back to A, who plays to C while B runs forward as third man to get C''s pass. B plays across to D, C comes to support, D plays back to C who feeds the next player A2. A2 passes for D running onto it, and the cycle continues with A2 moving to take B''s pass.', '1-2 touches', NULL, 'Timing of the forward third-man run; create width.', '7-9', 7, 9, '10 yard rhombus', 9.1, 9.1, NULL, false, false, false, NULL, 160),
  ('Double rhombus receive on back foot', 'passing_unopposed', 'unopposed', 'in_possession', 77, 77, 'Ancelotti 5', 'Ancelotti (Bayern Munich)', 'Progress the play (full backs, mids, attacking mids) receiving on the back foot with a directional first touch.', 'Two overlapping 10 yard rhombuses: A bottom, B and E inside, C and F wide, D top.', 'Sequence A-B-C-D-E-F-A. Everyone leaves their cone at an angle and takes a directional touch: B and E move forward and sideways, C and F drop back, D moves forward. Players follow their pass.', '1-2 touches', NULL, 'Back-foot receiving; width and depth; angled movements.', '10-12', 10, 12, '10 yard rhombus', 9.1, 9.1, NULL, false, false, true, NULL, 170),
  ('Outside-to-inside receive with outside foot', 'passing_unopposed', 'unopposed', 'in_possession', 78, 78, 'Ancelotti 6', 'Ancelotti (Bayern Munich)', 'Wide players move outside then inside to escape a marker and control with the outside of the foot.', 'Same six-position double rhombus (A-F), 10 yard sides.', 'Sequence A-B-C-D-E-F-A. C and F check out wide then come inside, control with the outside of the foot and pass; B, D and E step off at an angle with a directional touch.', '1-2 touches', NULL, 'Outside-to-inside movement to create space; receive on the move.', '10-12', 10, 12, '10 yard rhombus', 9.1, 9.1, NULL, false, false, true, NULL, 180),
  ('Third man run, receive, dribble, pass', 'passing_unopposed', 'unopposed', 'in_possession', 79, 79, 'Ancelotti 7', 'Ancelotti (Bayern Munich)', 'Deep third-man runs off the ball, then receive, dribble and pass.', 'Six-position double rhombus (A-F), 10 yard sides.', 'Sequence A-B-C-D-E-F-A. C and F drop back then time a forward run to receive on the move and dribble before passing; B and E step off at an angle and play diagonal passes timed for the runner.', '1-2 touches', NULL, 'Time the run off the ball; pass forward to break lines.', '10-12', 10, 12, '10 yard rhombus', 9.1, 9.1, NULL, false, false, true, NULL, 190),
  ('Inside support with give-and-go overlap', 'passing_unopposed', 'unopposed', 'in_possession', 80, 80, 'Ancelotti 8', 'Ancelotti (Bayern Munich)', 'Progress the play with inside support and a give and go around the wide player.', 'Six-position double rhombus (A-F), 10 yard sides.', 'A to B, B to C; C plays inside to B who has moved across, B passes forward for C running round the cone (give and go), C passes to D. The mirror sequence runs on the other side with D, E and F; F passes to the next A.', '1-2 touches', NULL, 'Timing of the overlap run; read the situation; play in tight areas.', '10-12', 10, 12, '10 yard rhombus', 9.1, 9.1, NULL, false, false, true, NULL, 200),
  ('Inside support then forward diagonal pass', 'passing_unopposed', 'unopposed', 'in_possession', 81, 81, 'Ancelotti 9', 'Ancelotti (Bayern Munich)', 'Progress the ball using inside support and an incisive forward pass.', 'Six-position double rhombus (A-F), 10 yard sides.', 'A passes wide to C who checks and drops; C plays inside to B, who has checked off his cone and come across; B hits a hard diagonal ground pass to D. Mirror on the other side with D, F and E; E passes to the next A.', '1-2 touches', NULL, 'Body shape; check away; accurate driven pass.', '10-12', 10, 12, '10 yard rhombus', 9.1, 9.1, NULL, false, false, true, NULL, 210),
  ('Continuous give-and-go support circuit', 'passing_unopposed', 'unopposed', 'in_possession', 82, 82, 'Ancelotti 10', 'Ancelotti (Bayern Munich)', 'Close combinations and one-twos between full backs and midfielders.', 'Six-position double rhombus (A-F), 10 yard sides.', 'A one-two with B then wide to C; C plays inside to B moving across; B passes forward for C overlapping round the cone; C to D. D give and go with E, passes to F; F give and go with E, then F passes to the next A.', '1-2 touches', NULL, 'Positioning, forward runs, play in tight areas.', '10-12', 10, 12, '10 yard rhombus', 9.1, 9.1, NULL, false, false, true, NULL, 220),
  ('Rhombus one-twos and lay-off runs', 'passing_unopposed', 'unopposed', 'in_possession', 85, 85, 'Guardiola 1', 'Guardiola (Bayern Munich)', 'Support play with one-twos and well-timed movement off the ball to receive, as a micro-game situation.', '10 yard rhombus A (base), B, C (top), D; extras queue at A.', 'A plays a one-two with B (B checks off his cone and drops), then passes to C who lays off for B running round his cone. B plays across to D, who lays off for C running round his cone; C slides D round his cone with a through pass and D passes to the next A.', '1-2 touches', NULL, 'Check away to escape the marker; game speed and intensity; mix short, long, support and through passes.', '7-9', 7, 9, '10 yard rhombus', 9.1, 9.1, NULL, false, false, false, NULL, 230),
  ('Rhombus one-twos and third man through pass', 'passing_unopposed', 'unopposed', 'in_possession', 86, 86, 'Guardiola 2', 'Guardiola (Bayern Munich)', 'One-twos and timing of movement with a through pass for a third man run.', '10 yard rhombus A, B, C, D; extras at A.', 'A one-two with B (B checks and drops); A passes to C who lays off for B running round his cone; B passes for C going round the cone; C plays a through pass to D, who dropped then ran forward. D finishes with a pass to the next A.', '1-2 touches', NULL, 'Timing of runs; body shape; incisive movement at game speed.', '7-9', 7, 9, '10 yard rhombus', 9.1, 9.1, NULL, false, false, false, NULL, 240),
  ('Rhombus receive on run, dribble, through pass', 'passing_unopposed', 'unopposed', 'in_possession', 87, 87, 'Guardiola 3', 'Guardiola (Bayern Munich)', 'Move to receive on the run, then dribble and play a through pass.', '10 yard rhombus A, B, C, D with a cone in the middle; extras at A.', 'A one-two with B; A to C who lays off for B running round his cone. B dribbles inside past the central cone and passes into the path of D, who checked away then made a third man run round his cone. D passes to the next A.', '1-2 touches', NULL, 'Step and control; first touch; incisive off-the-ball movement.', '7-9', 7, 9, '10 yard rhombus', 9.1, 9.1, NULL, false, false, false, NULL, 250),
  ('Support circuit receiving with marker behind', 'passing_unopposed', 'unopposed', 'in_possession', 88, 88, 'Guardiola 4', 'Guardiola (Bayern Munich)', 'Create space away from an opponent behind and receive with a directional touch in a support circuit.', '10 yard rhombus A (base), B (centre), C (right), D (top), E (left); extras at A.', 'A one-two with B, A moves across to get it back and passes wide to C. C plays inside to B who has come across, B passes on to D. D lays off for C running round the cone, C passes across to E. E lays off for D, who plays a through pass for E''s forward run; E passes to the next A.', '1-2 touches', NULL, 'Escape a marker from behind; width and depth; game speed.', '8-10', 8, 10, '10 yard rhombus', 9.1, 9.1, NULL, false, false, false, NULL, 260),
  ('Support circuit short, long, through', 'passing_unopposed', 'unopposed', 'in_possession', 89, 89, 'Guardiola 5', 'Guardiola (Bayern Munich)', 'Support circuit using short, long, support and through passes.', '10 yard rhombus A, B (centre), C, D (top), E; extras at A.', 'A one-two with B, comes across for the return and plays wide to C. C plays inside to B who moved forward then across; B passes forward to D. D one-two with E then plays a through pass for E''s overlap round the cone; E passes to the next A.', '1-2 touches', NULL, 'Directional control; vary pass types; game intensity.', '8-10', 8, 10, '10 yard rhombus', 9.1, 9.1, NULL, false, false, false, NULL, 270),
  ('Support, dribble across and through pass', 'passing_unopposed', 'unopposed', 'in_possession', 90, 90, 'Guardiola 6', 'Guardiola (Bayern Munich)', 'Movement to receive, support play, a dribble and a through pass.', '10 yard rhombus A, B (centre), C, D (top), E; extras at A.', 'A one-two with B, then wide to C; C plays inside to B who has moved, B passes forward to D. D lays off for C running round the cone; C dribbles across and plays a through pass for E''s run round his cone. E passes to the next A.', '1-2 touches', NULL, 'Escape a marker behind; incisive movement; directional touches.', '8-10', 8, 10, '10 yard rhombus', 9.1, 9.1, NULL, false, false, false, NULL, 280),
  ('Rhombus plus triangle complex support circuit', 'passing_unopposed', 'unopposed', 'in_possession', 91, 91, 'Guardiola 7', 'Guardiola (Bayern Munich)', 'Complex support circuit combining a triangle and a rhombus with lay-offs and a long through ball.', '8 yard triangle (A, B, C) joined to a 10 yard rhombus (B, D, E, F); extras at A.', 'A to B, B to C; C comes inside, opens up and dribbles forward, then passes diagonally to F who dropped and ran round his cone. B spins to take F''s lay-off and passes to E, who cuts in and lays back for D''s run; D plays a long through ball for F''s deep overlap round the cone. F passes to the next A.', '1-2 touches', NULL, 'Checking away; width and depth; game speed.', '10-12', 10, 12, '8 yard triangle + 10 yard rhombus', 9.1, 9.1, NULL, false, false, false, NULL, 290),
  ('Complex circuit through pass to third man', 'passing_unopposed', 'unopposed', 'in_possession', 92, 92, 'Guardiola 8', 'Guardiola (Bayern Munich)', 'Complex triangle-rhombus circuit ending in a long diagonal through ball for a third man overlap.', '8 yard triangle (A, B, C) and 10 yard rhombus (B, D, E, F); extras at A.', 'A one-two with B, then A to C, who opens up and plays wide to D. B moves forward and across to get D''s inside pass and plays forward to E. E lays back for D''s curved run round the cone; D plays a long diagonal through ball for F''s deep overlap after dropping. F passes to the next A.', '1-2 touches', NULL, 'Escape the marker from behind; incisive movement.', '10-12', 10, 12, '8 yard triangle + 10 yard rhombus', 9.1, 9.1, NULL, false, false, false, NULL, 300),
  ('Complex support circuit with give-and-go', 'passing_unopposed', 'unopposed', 'in_possession', 93, 93, 'Guardiola 9', 'Guardiola (Bayern Munich)', 'Complex triangle-rhombus circuit finished with a one-two and through pass for an overlap.', '8 yard triangle (A, B, C) and 10 yard rhombus (B, D, E, F); extras at A.', 'A one-two with B, then A to C, who opens up and plays wide to D. B moves forward then across to take D''s inside pass and plays forward to E (double movement). E one-two with F then plays through for F overlapping round the cone; F passes to the next A.', '1-2 touches', NULL, 'Double movement to create space; directional control.', '10-12', 10, 12, '8 yard triangle + 10 yard rhombus', 9.1, 9.1, NULL, false, false, false, NULL, 310),
  ('Complex circuit with triangle patterns', 'passing_unopposed', 'unopposed', 'in_possession', 94, 94, 'Guardiola 10', 'Guardiola (Bayern Munich)', 'Triangle tactical patterns inside a complex support circuit: lay-off, give and go and deep overlap.', '8 yard triangle (A, B, C) and 10 yard rhombus (B, D, E, F); extras at A.', 'A to B, B to C who comes inside, opens up and dribbles forward. C passes diagonally to F, who dropped and ran round his cone; B spins to take F''s lay-off and passes to E. E plays a give and go with D, receiving after running round his cone, then plays through for F''s deep curved overlap; F passes to the next A.', '1-2 touches', NULL, 'Width and depth; timing of curved runs.', '10-12', 10, 12, '8 yard triangle + 10 yard rhombus', 9.1, 9.1, NULL, false, false, false, NULL, 320),
  ('Y-shape basic passing and receiving circuit', 'passing_unopposed', 'unopposed', 'in_possession', 97, 97, 'Sarri 1', 'Sarri (Napoli)', 'Basic passing and receiving in a tactical Y shape with timed checking movements and quick synchronised play.', 'Y shape with 10 yard distances: A at the base, B in the middle, C at the top centre, D and D1 at the two top corners; extras queue at A.', 'A passes to B, who leaves his cone and opens up; C moves to one side of his cone and B passes forward to him. C plays to D, who steps off and opens up, then D dribbles back and passes to the next A. Next rep goes to D1 on the other side.', '1-2 touches', 'Alternate sides using D1.', 'Check away before receiving; form rhombus and triangle shapes with two support options for the ball carrier.', '10-12', 10, 12, '10 yard distances', NULL, NULL, NULL, false, false, true, NULL, 330),
  ('Y-shape check, one-two, through pass deep run', 'passing_unopposed', 'unopposed', 'in_possession', 98, 98, 'Sarri 2', 'Sarri (Napoli)', 'Synchronised combination play with game timing: accurate, well-weighted passes for well-timed runs.', 'Same Y shape, 10 yard distances, A, B, C, D and D1.', 'A passes to B; C slides to one side of his cone and B feeds him. C plays a one-two with D, coming across for the return. D checks off, comes back to return the pass, then makes a third movement the other way to run onto C''s through ball. D dribbles and passes to the next A; repeat on the D1 side.', '1-2 touches', 'Alternate sides using D1.', 'Timing of the three movements; weight of the through ball.', '10-12', 10, 12, '10 yard distances', NULL, NULL, NULL, false, false, true, NULL, 340),
  ('Y-shape triple movement and overlap run', 'passing_unopposed', 'unopposed', 'in_possession', 99, 99, 'Sarri 3', 'Sarri (Napoli)', 'Synchronised combination play with a triple movement (check, drop, overlap) to receive.', 'Same Y shape, 10 yard distances, A, B, C, D and D1.', 'A passes to B, who steps off and opens up. D checks and drops to take B''s diagonal pass and lays it to C. C meets the lay-off and plays a through ball for D overlapping (give and go). D runs with the ball and passes to the next A; repeat via D1.', '1-2 touches', 'Alternate sides using D1.', 'Check away to create space; support play; running with the ball.', '10-12', 10, 12, '10 yard distances', NULL, NULL, NULL, false, false, true, NULL, 350),
  ('Y-shape lay-off give-and-go, deep run', 'passing_unopposed', 'unopposed', 'in_possession', 100, 100, 'Sarri 4', 'Sarri (Napoli)', 'Fast combination play: forward pass, lay-off for a give and go, then a through ball for a deep run.', 'Same Y shape, 10 yard distances, A, B, C, D and D1.', 'A passes to B; C moves to one side and B passes forward to him. B moves to meet C''s lay-off and returns it for C running round his cone (give and go). D, after two movements, makes a third the opposite way to take C''s through pass, runs with it and passes to the next A; repeat via D1.', '1-2 touches', 'Alternate sides using D1.', 'Timing of checking away and runs without the ball; incisive runs and overlaps.', '10-12', 10, 12, '10 yard distances', NULL, NULL, NULL, false, false, true, NULL, 360),
  ('Short triangle combo, through ball for overlap', 'passing_unopposed', 'unopposed', 'in_possession', 101, 101, 'Sarri Practice 5', 'Sarri (Napoli)', 'Synchronised combinations, timing of checking away and incisive runs off the ball.', 'Diamond-shaped circuit of cones about 10 yards apart with players A (start, queue), B, C, D and D1 on the far side.', 'A feeds B; C slips to the side of his cone and B plays forward to him. B steps up for C''s lay-off while D checks and drops for B''s pass; D plays a give-and-go with C, loops round his cone for the return and dribbles back to the A queue. Repeat on the D1 side.', '1-2 touches', NULL, 'Body shape, check away to create space, use width and depth.', '10-12 (4-6 extra)', 10, 12, '10 yard distances', 9.1, 9.1, NULL, false, false, false, NULL, 370),
  ('Short triangle combo, overlap version 2', 'passing_unopposed', 'unopposed', 'in_possession', 102, 102, 'Sarri Practice 6', 'Sarri (Napoli)', 'Synchronised combinations, check-away timing, incisive runs and overlaps.', 'Same diamond circuit with 10 yard distances: A queue, B, C, D and D1.', 'A to B; C slides off his cone and receives from B, lays off to B who returns it for C spinning round the cone. D checks, takes C''s pass and gives it back, then C slides a through ball for D''s opposite run; D dribbles back to the start. Alternate with D1.', '1-2 touches', NULL, 'Opposite movements, body shape, check away before receiving.', '10-12 (4-6 extra)', 10, 12, '10 yard distances', 9.1, 9.1, NULL, false, false, false, NULL, 380),
  ('Forward pass, support, give-and-go overlap', 'passing_unopposed', 'unopposed', 'in_possession', 103, 103, 'Sarri Practice 7', 'Sarri (Napoli)', 'Synchronised combinations, check-away timing, support play and overlapping runs.', 'Diamond circuit with 10 yard distances: A queue, B, C, D, D1.', 'A plays B; C comes off his cone and takes B''s forward pass, then finds D who has checked away at an angle. D sets it for B''s forward run, B gives it back to complete the one-two and D dribbles to the A queue. Repeat with D1.', '1-2 touches', NULL, NULL, '10-12 (4-6 extra)', 10, 12, '10 yard distances', 9.1, 9.1, NULL, false, false, false, NULL, 390),
  ('Deep forward pass, give-and-go in rhombus', 'passing_unopposed', 'unopposed', 'in_possession', 104, 104, 'Sarri Practice 8', 'Sarri (Napoli)', 'Timing of checking away and movement without the ball in a synchronised combination.', '10 yard rhombus: A (queue) at the bottom, B on the left point, C at the top, empty right point.', 'A drives a firm ground pass up to C, who opens up with a directional touch round his cone. B checks back then comes inside for C''s lay-off and switches it across the rhombus for C''s curved run round the cone; C dribbles back to the A queue.', '1-2 touches', NULL, NULL, '6-8 (2-4 extra)', 6, 8, '10 yard rhombus', 9.1, 9.1, NULL, false, false, false, NULL, 400),
  ('One-two, deep pass, third man run', 'passing_unopposed', 'unopposed', 'in_possession', 105, 105, 'Sarri Practice 9', 'Sarri (Napoli)', 'Timing of check-aways and synchronised combination play with a third man run.', '10 yard rhombus: A (queue) bottom, B left, C top.', 'A plays a one-two with B who has dropped, opening up round the cone for the return and then passing up to C who moves off his cone. B curls round his cone to take C''s lay-off and plays across for C''s curved run; C dribbles back to the start.', '1-2 touches', NULL, NULL, '6-8 (2-4 extra)', 6, 8, '10 yard rhombus', 9.1, 9.1, NULL, false, false, false, NULL, 410),
  ('Three-player combos in double triangle', 'passing_unopposed', 'unopposed', 'in_possession', 106, 106, 'Sarri Practice 10', 'Sarri (Napoli)', 'Game-like three-player combinations with synchronised movement patterns.', 'Two mirrored triangles side by side, 10 yard distances: A queue bottom right and A1 queue bottom left, B and B1 in the middle, C and C1 at the top.', 'A plays a one-two with B (moving forward at an angle), then hits a diagonal ground pass to C who comes off his cone. C sets back for B''s forward run, B returns it to complete the give-and-go and C dribbles to the A1 queue. The sequence then runs mirrored from A1 via B1 and C1.', '1-2 touches', NULL, NULL, '10-12 (2-4 extra)', 10, 12, '10 yard distances', 9.1, 9.1, NULL, false, false, false, NULL, 420),
  ('Triangle passing circuit through cone gates', 'passing_unopposed', 'unopposed', 'in_possession', 109, 109, 'Emery Practice 1', 'Emery (Sevilla)', 'Accurate passing and oriented first touch inside the triangle shape.', '10 yard triangle of cone gates: A queue at one corner, B at the bottom corner, C at the third corner (2 per cone max).', 'A passes to B through the cone gate; B steps off his cone and takes a directional touch round it, then passes on to C who does the same and plays to the next A. Each player follows his pass.', '1-2 touches', 'Reverse the direction.', 'Body shape, move to create space, open up for the next pass.', '6-8 per group (2 per cone + 2 extra)', 6, 8, '10 yard triangle', 9.1, 9.1, NULL, false, false, false, NULL, 430),
  ('Directional touch through gate, beat mannequin', 'passing_unopposed', 'unopposed', 'in_possession', 110, 110, 'Emery Practice 2', 'Emery (Sevilla)', 'Oriented control, running with the ball and a feint to get past a defender.', '10 yard triangle of cone gates: A queue at one corner, B at the bottom corner, C at the third corner (2 per cone max). A mannequin stands on the C-to-A side.', 'A plays B, who drops off his cone and passes to C. C takes a directional touch from behind his cone through the gate, dribbles at the mannequin, feints and goes past either side, then passes to the next A.', '1-2 touches', NULL, NULL, '6-8 per group', 6, 8, '10 yard triangle', 9.1, 9.1, NULL, false, false, false, NULL, 440),
  ('Double one-two, dribble and feint', 'passing_unopposed', 'unopposed', 'in_possession', 111, 111, 'Emery Practice 3', 'Emery (Sevilla)', 'One-two combinations, control on the move, then dribbling and a feint past a defender.', '10 yard triangle of cone gates: A queue at one corner, B at the bottom corner, C at the third corner (2 per cone max). Mannequin between C and A.', 'A and B play a one-two, A passes across to C who has dropped, and B curls round his cone to take C''s pass. C then plays a give-and-go with B, curving through the cone gate for the return, dribbles up to the mannequin, feints past it and passes to the next A.', '1-2 touches', NULL, NULL, '6-8 per group', 6, 8, '10 yard triangle', 9.1, 9.1, NULL, false, false, false, NULL, 450),
  ('Quick combo, through pass, third man run', 'passing_unopposed', 'unopposed', 'in_possession', 112, 112, 'Emery Practice 4', 'Emery (Sevilla)', 'Combination play, creating space and an incisive third man run onto a through pass.', '10 yard triangle of cone gates: A queue at one corner, B at the bottom corner, C at the third corner (2 per cone max). Mannequin between C and A.', 'A and B play a one-two, then B spins round his cone and receives again from A. C checks away first, then runs forward past the mannequin to take B''s through pass on the move and dribbles to the next A.', '1-2 touches', NULL, 'Check away before the run, receive on the move.', '6-8 per group', 6, 8, '10 yard triangle', 9.1, 9.1, NULL, false, false, false, NULL, 460),
  ('Close combination, incisive pass on the move', 'passing_unopposed', 'unopposed', 'in_possession', 113, 113, 'Emery Practice 5', 'Emery (Sevilla)', 'Tight-space combination play, support and timing a run off the ball.', '10 yard triangle: A queue bottom left, B bottom right, C at the top (2 per cone max).', 'A passes to B and follows to support; B plays a give-and-go with A while circling his cone for the return. C checks away then times his run to take B''s pass across, controls on the move and passes to the next A.', '1-2 touches', NULL, NULL, '6-8 per group', 6, 8, '10 yard triangle', 9.1, 9.1, NULL, false, false, false, NULL, 470),
  ('Triangle support with double give-and-go', 'passing_unopposed', 'unopposed', 'in_possession', 114, 114, 'Emery Practice 6', 'Emery (Sevilla)', 'Short combinations, oriented first touch and escaping markers in tight space.', '10 yard triangle: A queue bottom left, B bottom right, C at the top (2 per cone max).', 'A passes to B and follows; B does a give-and-go with A round his cone, then passes to C who has dropped. C plays a give-and-go with B, circling his own cone for the return, then takes a directional touch and passes to the next A.', '1-2 touches', NULL, NULL, '6-8 per group', 6, 8, '10 yard triangle', 9.1, 9.1, NULL, false, false, false, NULL, 480),
  ('Triangle support, forward pass and give-and-go', 'passing_unopposed', 'unopposed', 'in_possession', 115, 115, 'Emery Practice 7', 'Emery (Sevilla)', 'Mixing wide and forward passes with synchronised support movements.', '10 yard triangle: A queue bottom left, B bottom right, C at the top (2 per cone max).', 'A passes to B and follows; B sets it back to A and runs round his cone to support C. A plays forward to C, who does a give-and-go with B while moving round his cone, then takes a directional touch and passes to the next A.', '1-2 touches', NULL, NULL, '6-8 per group', 6, 8, '10 yard triangle', 9.1, 9.1, NULL, false, false, false, NULL, 490),
  ('Triangle support, forward pass and lay-off', 'passing_unopposed', 'unopposed', 'in_possession', 116, 116, 'Emery Practice 8', 'Emery (Sevilla)', 'Sharp, quick combination play with support and unmarking runs.', '10 yard triangle: A queue bottom left, B bottom right, C at the top (2 per cone max).', 'A passes to B and follows; B lays it back to A and runs round his cone. A plays forward to C, who lays it off for B''s run; B takes a directional touch on the move and passes to the next A.', '1-2 touches', NULL, NULL, '6-8 per group', 6, 8, '10 yard triangle', 9.1, 9.1, NULL, false, false, false, NULL, 500),
  ('Triangle circuit with dummy and one-two', 'passing_unopposed', 'unopposed', 'in_possession', 117, 117, 'Emery Practice 9', 'Emery (Sevilla)', 'Quick combinations in small spaces using a dummy to take opponents out.', '10 yard triangle with two players at each point: A/D2 bottom left, B1/B2 bottom right, C1/C2 top, D1 near A.', 'A plays towards B1, who lets it run through his legs; B2 picks it up and plays a short give-and-go with B1 (circling the cone). B2 passes on to C1 and the same dummy plus one-two repeats at the top and then at the bottom left, with D1 passing to D2 who becomes the new A.', '1-2 touches', NULL, 'Sell the dummy, check away from markers, then move again to receive.', '9-10 (2-3 extra)', 9, 10, '10 yard triangle', 9.1, 9.1, NULL, false, false, false, NULL, 510),
  ('Triangle circuit with lay-offs, third man runs', 'passing_unopposed', 'unopposed', 'in_possession', 118, 118, 'Emery Practice 10', 'Emery (Sevilla)', 'Fast one-twos and well-timed third man runs off lay-off passes.', '10 yard triangle with two players at each point: A/D2, B1/B2, C1/C2 (plus D1).', 'A passes to B1 and gets the return, then plays for B2''s third man run off the cone. B2 passes forward to C1, who checks back and lays off to B2 moving forward, who finds C2''s third man run. The pattern repeats on the last side and D1 finishes with a pass to D2, who becomes the new A.', '1-2 touches', NULL, NULL, '9-10 (2-3 extra)', 9, 10, '10 yard triangle', 9.1, 9.1, NULL, false, false, false, NULL, 520),
  ('Creating space in a Y-shape circuit', 'passing_unopposed', 'unopposed', 'in_possession', 121, 121, 'Simeone Practice 1', 'Simeone (Atletico Madrid)', 'Game timing in the Y shape: checking away from markers in different ways before receiving.', 'Y-shape circuit: start queues A and A1 at the bottom, B and B1 at central cones 10 yards up, C and C1 at the top corners of a 12 yard triangle. Left and right sides can run at the same time.', 'A passes to B, who calls which side to play, moves off his cone, opens up and plays diagonally to C. C comes off his cone, takes a directional touch round it, dribbles down and passes to the next A. Then repeat via B1 and C1.', '1-2 touches', NULL, 'Communicate the side, check up/down/across, open the body.', '10-12 (2-4 extra)', 10, 12, '10 yard line / 12 yard triangle', 9.1, 11.0, NULL, false, false, false, NULL, 530),
  ('Y-shape forward run for return, give-and-go', 'passing_unopposed', 'unopposed', 'in_possession', 122, 122, 'Simeone Practice 2', 'Simeone (Atletico Madrid)', 'Game timing in the Y shape with a forward run to receive the return pass.', 'Y-shape circuit: start queues A and A1 at the bottom, B and B1 at central cones 10 yards up, C and C1 at the top corners of a 12 yard triangle. Left and right sides can run at the same time.', 'A to B, who calls the side, checks away, opens up and plays diagonally to C. C steps forward and lays it back for B''s diagonal forward run; B plays into C''s path as C spins round his cone (give-and-go). C dribbles to the next A; repeat via B1 and C1.', '1-2 touches', NULL, NULL, '10-12 (2-4 extra)', 10, 12, '10 yard line / 12 yard triangle', 9.1, 11.0, NULL, false, false, false, NULL, 540),
  ('Y-shape one-two, long pass, third man run', 'passing_unopposed', 'unopposed', 'in_possession', 123, 123, 'Simeone Practice 3', 'Simeone (Atletico Madrid)', 'Game timing in the Y shape combining a one-two, long pass and third man run.', 'Y-shape circuit: start queues A and A1 at the bottom, B and B1 at central cones 10 yards up, C and C1 at the top corners of a 12 yard triangle. Left and right sides can run at the same time.', 'B calls the side and plays a one-two with A. A then hits a long pass to C coming off his cone; C lays back for B''s diagonal third man run, and B slips it into C''s path round the cone. C dribbles to the next A; repeat on the A1/B1/C1 side.', '1-2 touches', NULL, NULL, '10-12 (2-4 extra)', 10, 12, '10 yard line / 12 yard triangle', 9.1, 11.0, NULL, false, false, false, NULL, 550),
  ('Y-shape deep pass, lay-off, third man', 'passing_unopposed', 'unopposed', 'in_possession', 124, 124, 'Simeone Practice 4', 'Simeone (Atletico Madrid)', 'Timing of check-aways and synchronised third man runs.', 'Y-shape circuit: start queues A and A1 at the bottom, B and B1 at central cones 10 yards up, C and C1 at the top corners of a 12 yard triangle. Left and right sides can run at the same time.', 'A plays long to C who comes forward off his cone; C lays back for B''s diagonal third man run and B passes into C''s path round the cone to finish the give-and-go. C dribbles to the next A; repeat via A1, B1, C1.', '1-2 touches', NULL, NULL, '10-12 (2-4 extra)', 10, 12, '10 yard line / 12 yard triangle', 9.1, 11.0, NULL, false, false, false, NULL, 560),
  ('Double triangle with varied receiving movements', 'passing_unopposed', 'unopposed', 'in_possession', 125, 125, 'Simeone Practice 5', 'Simeone (Atletico Madrid)', 'Timing of check-aways, synchronised runs and switching play.', 'Double triangle / Y shape: A queue at the bottom, B at a central cone 10 yards up, C top right and D top left forming a 12 yard triangle.', 'B drops to one side and plays a one-two with A, who then hits a long diagonal to C (who has checked and dropped). C sets it back for B moving forward, B switches across to D, who has pushed up then opens up, takes a directional touch round his cone and dribbles to the start.', '1-2 touches', NULL, NULL, '7-9 (2-4 extra)', 7, 9, '10 yard line / 12 yard triangle', 9.1, 11.0, NULL, false, false, false, NULL, 570),
  ('Double triangle give-and-go and third man', 'passing_unopposed', 'unopposed', 'in_possession', 126, 126, 'Simeone Practice 6', 'Simeone (Atletico Madrid)', 'Check-away timing and incisive third man runs into space.', 'Double triangle / Y shape: A queue at the bottom, B at a central cone 10 yards up, C top right and D top left forming a 12 yard triangle.', 'B drops, one-two with A, A plays long diagonal to C. C lays back to B''s forward run and B returns it as C spins round his cone (give-and-go). C then slides an angled pass into D''s third man run; D dribbles back to the start.', '1-2 touches', NULL, NULL, '7-9 (2-4 extra)', 7, 9, '10 yard line / 12 yard triangle', 9.1, 11.0, NULL, false, false, false, NULL, 580),
